    {"slot": 24, "item_id": "15-002", "type": "procedure", "modals": ["枷号游迎拘当苦役"],
     "condition": "弭盗五曰禁淫赌之徒", "subject": "乡甲",
     "action": "四民之业三五为羣良善之人数十结社有何不可，凡系棍徒但有成群合伙寺庙赌愽或开张之家收打头钱者，乡甲指实密报，除问罪外枷号游迎拘当苦役，仍重赏告人；娼优之家但有不识姓名男子使钱宽绰色状张皇即密报，有司审实者一体重赏，贪财容隐者事发一体重究",
     "object": "淫赌", "purpose": "禁淫赌", "punishment": "枷号游迎拘当苦役；贪财容隐一体重究", "confidence": "high"},
