    {"slot": 27, "item_id": "15-002", "type": "procedure", "modals": ["立一团长", "两家与盗同罪"],
     "condition": "弭盗八曰密远僻之防", "subject": "有司",
     "action": "郊关村落人烟辏集保甲一严盗自衰止，惟深山穷谷人迹罕至虽无可劫之家多栖行劫之辈；除有庄田势难迁移者听其孤庄，仍于邻近十里之内立一团长，令其挨家三三相保，团长统之，一家为盗两家同首，不首者别三发觉，团长申呈两家与盗同罪；其结山为寨者就立寨长以保甲法统之，仍以礼义化之，负固为盗者或招抚而散处之或堑其山谷不与民通或夷井伐木不使安居，甚者以兵剿擒之",
     "object": "远僻", "purpose": "密远僻防", "punishment": "两家与盗同罪", "confidence": "high"},
