    {"slot": 51, "item_id": "15-006", "type": "procedure", "modals": ["保领在外"],
     "condition": "仓犯收禁范围", "subject": "有司",
     "action": "古者罪人无闲坐之理，城垣则令之修筑鬼薪则令之劈柴仓庾则令之舂米，今以罪人拘系在仓犹有古之遗意；但仓犯原非重罪，充军发站人犯虽送监不妨，笞杖及赎徒令里族之长乡甲之人保领在外，至听讼之日不悞听问，申详之后不悞赎决可也；惟是隔县关提又当解审无人保领及监追还官钱粮家属不当保领者然后送仓，能几何人哉；近查几处州县专听皂快禀说，有钱者讨保在外无钱者不论罪情轻重一槩送仓；至于妇人收禁惟有犯奸死罪两条，余俱责付本夫收管，无夫者责付有服亲属邻里保管随衙听候，并无杂犯送监仓之文；其监追钱粮家属并无妇女，虽盗贼捕限亦无监禁家属之文，果其夫其父盗情已真仓禁妻子犹可，如招攀在逃无赃无证之人而滥禁妻子已属胡涂，甚者监其父母兄长不亦孟浪之甚乎，余于风宪约槩言之矣再引律条试自检查",
     "object": "仓犯", "purpose": "仓犯有等", "punishment": "", "confidence": "high"},
    {"slot": 52, "item_id": "15-006", "type": "procedure", "modals": ["处土作模令犯人多托坏堑"],
     "condition": "仓中设施", "subject": "各州县掌印官",
     "action": "仓中亦须穿井多备水桶几只，一则便于犯人自汲一则可防不测火烛；近查得一仓久犯轮当火头刁索后来贫犯已经重究外，各州县掌印官即处土作模令犯人多托坏堑，择于空便仓中作炕五七处计可容百人者，厚织草苫五寸大作芦席一重，乂作火灶三五处各从便食，再置麄碗碟百十个箸百十双，或照监中法官出薪米塩菜，待出仓之日贫者准开囚粮不贫者照数补谷；其家火等项新旧斗级交代损失者本人赔补；但有火头斗级人等多开饭钱强当衣帽及刁难犯人卧无席之地忍有米之饥者重行究治，仍枷号于本仓门首示众",
     "object": "仓中", "purpose": "仓犯得所", "punishment": "火头斗级多开饭钱强当衣帽重行究治枷号示众", "confidence": "high"},
    {"slot": 53, "item_id": "15-006", "type": "procedure", "modals": ["每日点判"],
     "condition": "监仓两簿", "subject": "掌印官",
     "action": "监仓两簿掌印官每日点判，要见某人某日送仓缘何久禁，某人某佐贰送仓因何事情；仍令斗级每辰口报仓犯有无饥寒病疾；其送饭之规务同监饭齐进，亦照监犯立为簿籍照序点名亲接；仓犯家人许径进仓中事毕放出，不许斗级拦阻；仓门之下亦置鼓一面以备仓犯声冤实时唤审",
     "object": "仓簿", "purpose": "仓犯稽核", "punishment": "", "confidence": "high"},
    {"slot": 54, "item_id": "15-006", "type": "procedure", "modals": ["俱不许擅拘仓禁"],
     "condition": "老幼病丧不仓禁", "subject": "有司",
     "action": "七十以上老人及十五以下儿男及大小女子及身有疾病新遭重丧，不系谋反大逆同居亲属俱不许擅拘仓禁；其随衙妇人上堂先问皂隶拘唤有无掏摸衙门人等曾否调戏，如有指名禀出者加倍重责革役，风宪约中言之矣兹再申明",
     "object": "老幼病丧", "purpose": "老幼不仓禁", "punishment": "皂隶掏摸调戏指名禀出加倍重责革役", "confidence": "high"},
    {"slot": 55, "item_id": "15-006", "type": "procedure", "modals": ["止令限办"],
     "condition": "拖欠钱粮限办", "subject": "有司",
     "action": "拖欠钱粮止令限办，入官财物止令限纳，给主财物止令限还，纸谷罪赎止令限完，各令保人领催，不则禀拘责治；如家贫无办讨保无人即令仓死何益，如可以经营有人保领仓之反妨措处；至于审罪之时便问干证人等本犯果否有力能否完纳方拟罪名，若果身家真无亏兑自当减赃银注无力，既省比销未完亦免累年仓比；其罪恶深重之人宁陆续多责及枷号示众亦足示惩；近见申详徒杖好问有稍等力甚至赃应给主辄捏主无全在及非本主自告名色俱改入官，不知此出何律，及允详之后却乃仓追严比淹禁岁月甚者着落亲族代纳，如此作官民生何以自存耶",
     "object": "拖欠钱粮", "purpose": "不滥仓比", "punishment": "", "confidence": "high"},
    # ===== 条7 驿犯 =====
    {"slot": 56, "item_id": "15-007", "type": "procedure", "modals": ["查盘官到"],
     "condition": "驿犯五等", "subject": "驿官/守令",
     "action": "驿递之官虽卑生死之权实重，谚云活军死徒，盖发站之徒率有五等：一等颇有身家纳赎既惜多费摆站又怕辱名，到驿之日官吏先行贿赂保人图得货财收管出门犯人离驿；一等奸顽积棍无力赎徒，到驿之日私查徒数暗记官赃挟制官吏假取衣粮驿递不敢不放，此两等人查盘官到或保人代觅点站或本人探听亲来，查盘既过依旧回家；一等供给无人乞食不足或不耐锁押买通押解之人脱逃回家，驿官自歉多弊明知不敢声言或差人需索些须，点站之时反为觅替，此三等人全不在驿皆徒夫之奸顽者也；一等才能可用或图衣食私役于积年保歇之家，或求亲幸听差于衙门奔走之事，甚有役满之后依恋不归者；一等百事无长一贫如洗，官吏要索不遂捶楚常加，牢头买免无钱凌虐备至，饥寒与筞疾病不恤，及至死亡只费报故纸一张耳，此等之人常居其半守令首当注意者也",
     "object": "徒犯", "purpose": "驿犯有等", "punishment": "", "confidence": "high"},
    {"slot": 57, "item_id": "15-007", "type": "procedure", "modals": ["另行查报以便批发"],
     "condition": "驿递简繁查报", "subject": "各驿递",
     "action": "驿递有冲有次冲，有居民多至数百家者有不及百家者，院道批发徒犯率从就近地方；且如永宁一州三驿，玉亭附在州城徒夫乞食为便，青龙不及玉亭然人烟颇称辏集，惟是吴城一驿夹在荒山人家既少且贫徒犯批发颇众，解到之日不脱逃则饿死，上司何由知之；除驿递简繁人家多少另行查报以便批发外，其在各驿递囚犯要见本驿居民若干家见充徒犯若干人，以便量情改调；如官吏厌惧囚多故捏监墙倾圯店舍稀疏者核实提问",
     "object": "驿递", "purpose": "批发得宜", "punishment": "捏报倾圯者核实提问", "confidence": "high"},
    {"slot": 58, "item_id": "15-007", "type": "procedure", "modals": ["每年终一报"],
     "condition": "囚房修葺", "subject": "掌印官",
     "action": "囚房狼狈倾颓驿递尤甚，何者丞使痛痒不关守令耳目不及钱粮无所措处兴作谁肯申呈，是以浅隘之房卑湿之地漏雨穿风浸泥濡水盛暑蒸溽大寒凄冽，人非木石安能二三年不病且死哉；查盘官点囚多不下驿入驿亦不看房；以后掌印官每年终一报监仓驿递养济等房有无塌漏应否修葺，果当兴工即于官路取木徒夫托坯，或破坏寺庙或人家废房旧砖瓦门牕皆堪拆买；地基要高门牕要厚，多作连炕厚铺苫席，再置锅灶碗碟杓瓢盆箸钢桶等器皿令馆夫收掌交代；每徒夫十人立火头二人专管汲水造饭，早间各吃粥一飡，饭后押令乞食，大率粥米三人一升三十人纔用一斗，即令各夫造；如果不齐亦听情愿，此辈罪人非因做工缺食寻常生计不必官为设处也",
     "object": "囚房", "purpose": "囚房修葺", "punishment": "", "confidence": "high"},
    {"slot": 59, "item_id": "15-007", "type": "procedure", "modals": ["保放回家调理"],
     "condition": "病疾徒犯保放", "subject": "驿官/州县",
     "action": "病疾徒犯法当保放回家调理，痊可照日贴役；近来驿官放者竟不迨呼不放者不恤疾病甚为坏法；其家远身孤之囚即日报知州县拨医调理，但有延慢失调致令身死者该驿官吏径以凌虐罪囚提问再拟；其孤子亲在笃疾或亲死无人殡葬者报知州县正官准假，事毕照日补役",
     "object": "病犯", "purpose": "病犯保放", "punishment": "延慢失调致死者驿官吏以凌虐罪囚提问", "confidence": "high"},
    {"slot": 60, "item_id": "15-007", "type": "procedure", "modals": ["不许拘役并如律收赎释放"],
     "condition": "老疾徒犯释放", "subject": "驿递官吏",
     "action": "发驿之后或有黄肿痞块痨瘵衰羸瘫痪风痹脚手残疾两眼双瞽，及役虽未满年已七十者，驿递官吏即呈州县掌印官当堂验实，详具年齿病状申报原批衙门，所有未满日期不许拘役并如律收赎释放；但有需索刁难不与申报者驿递官提问",
     "object": "老疾徒犯", "purpose": "老疾得释", "punishment": "需索刁难不与申报者驿递官提问", "confidence": "high"},
    {"slot": 61, "item_id": "15-007", "type": "procedure", "modals": ["不得过十板"],
     "condition": "驿官钤束", "subject": "驿官",
     "action": "州县监仓切近掌印正官下情既易通闻羣小犹知忌惮，驿递之设半不同城官与吏卒情同猫鼠，不惟禁约为难亦且贪虐同术，吁天之声何由上达又朝夕在其掌握有冤亦不敢闻；以后发驿徒夫除驿夫牢头不许擅自殴打外，其驿官以法钤束应得责治者不得过十板；如有需索见面节仪卖歇等钱及私下非礼凌虐奉承不到将徒夫擅行敲朴者，许被害之人指实陈告以凭重究革职",
     "object": "驿夫", "purpose": "禁擅殴", "punishment": "擅行敲朴重究革职", "confidence": "high"},
    {"slot": 62, "item_id": "15-007", "type": "procedure", "modals": ["带镣做工"],
     "condition": "徒犯做工", "subject": "有司",
     "action": "徒犯本为工作，律有拘役入役贴役之文，如煎塩炒铁运炭之类；近来有力买官者尽行卖放，无钱觅保者又惧私逃，昼则锁押乞食夜则禁锢囚房，甚非立法本意；律云犯徒罪者带镣做工，带镣正防其逃做工正役其力；本司向以积凶大恶到驿即逃常发之远驿，细思驿远则供给为难无亲则借助不便，不若改之本州县驿递：一则系刑具以见乡曲激其愧悔之心，一则有同室为之供给不患饔飧之缺，责令托打坯挑浚城壕修理衙门推水搬柴守门廵夜【带镣杂于众中】办一切事务，可省一夫工食；其无父母兄弟妻子又无亲族供给者比照囚粮事例量给米食资其力量；如此则既得以功赎罪之法又无饥寒致死之虞；州县去驿递差远者有役不妨调用，昼则同夫押管夜则收禁仓中，如有保人听从其便",
     "object": "徒犯", "purpose": "带镣做工", "punishment": "", "confidence": "high"},
    {"slot": 63, "item_id": "15-007", "type": "procedure", "modals": ["夫八囚二"],
     "condition": "夫八囚二搭配", "subject": "有司",
     "action": "查得律例徒夫做工与摆站原是两事，摆站者发驿递抬摃重劳之也；今徒犯既无供给又惧辛苦且奔走又难带镣何以防其逃逸；及查摃夫一站雇人每日银七八分多者一钱，若以囚徒搭配额夫，夫八囚二令之相羁，囚日得银三分饱食可以自存，而以八人防二人亦可以免逃逸庶几稍得其用；至于初犯再犯剌字窃盗一无所用又费关防，自有繁劳之役令之带镣工作勤苦三年，既消磨其骄逸之性，如果无人供给亦量贴与米食，惟良有司调停之",
     "object": "徒夫", "purpose": "搭配防逃", "punishment": "", "confidence": "high"},
    {"slot": 64, "item_id": "15-007", "type": "procedure", "modals": ["重责枷号外仍加役调驿"],
     "condition": "徒犯不法", "subject": "驿递官/州县",
     "action": "徒犯原非良民奸暴固其常性，但驿官有过遂被要挟任其纵横不敢制伏：有凌夺同犯把持狱情者，有指称打点科敛重囚者，有抢骗衣食扰害居民者，有傲侮官吏不遵约束者，有径自逃回拘唤殴打公差者，诸恶不可尽指，俱许驿递官指实申呈本管州县究明，除重责枷号外仍加役调驿；其因申而讦告驿官虽实亦不准理",
     "object": "徒犯", "purpose": "惩徒犯恶", "punishment": "重责枷号仍加役调驿；讦告驿官虽实不准理", "confidence": "high"},
    # ===== 条8 辨盗 =====
    {"slot": 65, "item_id": "15-008", "type": "procedure", "modals": ["审本保本甲"],
     "condition": "辨盗审法", "subject": "守令",
     "action": "狱情之难察惟盗为最，其访之之术大槩有三：或平日剌字偷儿或流来乞食贫子或寺观游食僧道或赌博游手羣徒或寄住佣工穷汉则疑其人；或察其色貌或见有装携则疑其人；或经商自外或居住孤庒或孑立无与或不属保甲则疑其人；要之盗不出于此人而此人未必皆盗也；快壮欲获盗以要功善于伪赃，守令欲成狱以弥罪喜于得赃，失主贪见在之财厌日久之累利于认赃，有此三念何赃不真；盗贼之狱十九成于严刑，严刑之狱十五类非真盗；乡约保甲严则朝稽其生理暮考其出入，万一被诬但审本保本甲某人以何为生与谁往来某夜果否在家某家失盗以来此人一向何往，素日有无非为近日如何度日，是否与某有雠，家中器用及男女衣服首饰曾否见伊常穿，曾系某铺买来何人所做，家有银钱系何物所卖何人所与；如来非盗仍取保甲里邻宗族保结；其平日交游赌博棍徒者四肢惰慢而自奉丰者夜去明来者掐捻谷黍者往来面生可疑者神色恍惚踪迹诡秘言语支吾者所得非其所有而不知所从来者闻盗犯而携家以逃者【良民无意防攀故不思远避真盗留心败露故闻信豫逃】来路不明而潜寄寺观窑果者朝佣工于此而暮窜身于彼者，乡甲里邻定不保结；宁失不经，与其诬良民宁失真盗，真盗失犹有死时良民诬竟无生日",
     "object": "盗", "purpose": "辨盗慎狱", "punishment": "保甲里邻定不保结", "confidence": "high"},
    # ===== 条9 审失单式 =====
    {"slot": 66, "item_id": "15-009", "type": "procedure", "modals": ["掌印官当堂重责严审"],
     "condition": "失单填式", "subject": "掌印官",
     "action": "失主被盗先要点检所失何物，如衣服首饰银钱具写来厯以便备照搜赃；记不真者许向妇女经收着体之人一一备细抄来，如不依格式潦草泛开及审问之时口语含糊者必有骗赖情由，掌印官当堂重责严审明白亲笔注于单上；假如金环一双要审是何模样【如葫芦二珠拂珠之类】青金赤金原重几钱何人还与何人打造有无记号，凡金银首饰器皿之类俱照此审；绿叚男衣一领要审麦绿柳绿大云小云或系某花大折细折或系直身是旧是新整袖半袖何物作里里何颜色某铺买来某裁缝作有无记号【如油痕墨点酒渍火烧挂破补绽之类】；黄妆花女衣一件要审金黄柿黄鹅黄柳黄有花无花系是何花大领小领大袖小袖补系何鸟何花或圆或方何物作里何物作带有无滚边贴边某裁缝作；红妆花裙一条要审花红木红共是几幅甚么腰带几重膝拦或璎珞或海马或美人或杂花何铺所买甚么贴边某裁缝作；凡各色布帛衣服帕巾网帽膝衣鞋袜之类俱照此审；银钱若干要审系卖何物系典何地何人所还何年所积整锭半锭新钱旧钱；牛马驴骡甚么毛色多少年齿原同某牙买自何人是牝是牡是骟",
     "object": "失单", "purpose": "详审失单", "punishment": "潦草泛开口语含糊者当堂重责", "confidence": "high"},
    {"slot": 67, "item_id": "15-009", "type": "procedure", "modals": ["先称分两", "先杂他衣"],
     "condition": "搜赃验赃", "subject": "掌印官",
     "action": "以上各审毕掌印官封之收诸私衙；凡快壮搜赃与失主相见相通者百倍重处；搜赃之日先将失主拘禁一处，止令快壮与四邻起送到官取出失单；如首饰先称分两，如衣服先杂他衣，然后提出失主听其拣认；如物有相似争持不决者便问本盗及寄赃之家，此物从何买来何人所做何人所与，有无原主见存，何人见你穿带亦召其人而问之；即失主之物不能自认认得一半确然可凭者即是真赃",
     "object": "搜赃", "purpose": "验真赃", "punishment": "快壮搜赃与失主相见相通者百倍重处", "confidence": "high"},
